#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    
    int t;
    cin >> t;
    
    while(t--){
        int n;
        cin >>n;
        
        vector<ll> a(3*n);
        for(ll &x : a) cin >> x;
        
        sort(a.rbegin(),a.rend());
        vector<ll> pref(3*n+1);
        for(int i = 0; i<3*n; ++i)
        pref[i+1] = pref[i] + a[i];
        
        ll answer = 0;
        
        for(int A=0; A<=n; ++A){
            int lo = 0,hi = n - A;
            
            while(lo < hi){
                int B =(lo + hi + 1)/ 2;
                
                int q = A +2 *(B-1);
                
                int r = 3 * n -2 * A - (B-1);
                
                ll gain= a[q] + a[q +1] - 3LL * a[r-1];
                
                if(gain>=0)
                    lo =B;
                else
                    hi = B-1;
            }
            
            for(int B = max(0,lo - 1); 
            B<= min(n-A,lo+1);++B){
                int k = 3 *n -2 * A - B;
                
                ll cur =  2LL * pref[A] + pref[A+2*B] + 3LL * pref[k];
                
                answer = max(answer,cur);
            }
        }
        cout << answer << '\n';
    }
    
    return 0;
	
}
